{"verb":"exec_js","session_id":"debug-harness-1","cwd":"C:\dev\deepseek-harness","raw_body":"const { execSync } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');
const http = require('http');
const net = require('net');

function get(url, timeoutMs = 2500) {
  return new Promise((resolve) => {
    const req = http.get(url, { timeout: timeoutMs }, (res) => {
      let body = '';
      res.on('data', (c) => { body += c; if (body.length > 8000) { res.destroy(); } });
      res.on('end', () => resolve({ ok: true, status: res.statusCode, headers: res.headers, body: body.slice(0, 4000) }));
      res.on('error', (e) => resolve({ ok: false, error: String(e) }));
    });
    req.on('timeout', () => { req.destroy(); resolve({ ok: false, error: 'timeout' }); });
    req.on('error', (e) => resolve({ ok: false, error: e.code || String(e.message) }));
  });
}

function post(url, payload, timeoutMs = 4000) {
  return new Promise((resolve) => {
    const u = new URL(url);
    const data = JSON.stringify(payload);
    const req = http.request({ hostname: u.hostname, port: u.port, path: u.pathname, method: 'POST', timeout: timeoutMs, headers: { 'content-type': 'application/json', 'content-length': Buffer.byteLength(data) } }, (res) => {
      let body = '';
      res.on('data', (c) => { body += c; if (body.length > 20000) res.destroy(); });
      res.on('end', () => {
        let parsed = body;
        try { parsed = JSON.parse(body); } catch {}
        resolve({ ok: true, status: res.statusCode, body: parsed });
      });
    });
    req.on('timeout', () => { req.destroy(); resolve({ ok: false, error: 'timeout' }); });
    req.on('error', (e) => resolve({ ok: false, error: e.code || String(e.message) }));
    req.write(data);
    req.end();
  });
}

function probePort(port, timeoutMs = 800) {
  return new Promise((resolve) => {
    const s = net.connect({ host: '127.0.0.1', port, timeout: timeoutMs }, () => { s.destroy(); resolve({ port, open: true }); });
    s.on('timeout', () => { s.destroy(); resolve({ port, open: false, error: 'timeout' }); });
    s.on('error', (e) => resolve({ port, open: false, error: e.code || String(e.message) }));
  });
}

(async () => {
  const home = process.env.FREDDIE_HOME || path.join(os.homedir(), '.freddie');
  const sessionId = process.env.FREDDIE_SESSION_ID || 'unknown';
  const jsonl = process.env.FREDDIE_SESSION_JSONL || '';
  const out = {
    node: process.version,
    pid: process.pid,
    ppid: process.ppid,
    cwd: process.cwd(),
    platform: process.platform,
    env: {
      FREDDIE_HOME: process.env.FREDDIE_HOME || null,
      FREDDIE_SESSION_ID: process.env.FREDDIE_SESSION_ID || null,
      FREDDIE_SESSION_JSONL: process.env.FREDDIE_SESSION_JSONL || null,
      FREDDIE_WEB_URL: process.env.FREDDIE_WEB_URL || null,
      FREDDIE_SHELL: process.env.FREDDIE_SHELL || null,
    },
    home,
    sessionId,
  };

  const lockPath = path.join(home, 'sessions', '--C-dev-deepseek-harness--', 'writer.lock');
  out.writerLockPath = lockPath;
  out.writerLockExists = fs.existsSync(lockPath);
  if (out.writerLockExists) {
    try { out.writerLock = fs.readFileSync(lockPath, 'utf8'); } catch (e) { out.writerLockError = String(e); }
  }

  const sessDir = jsonl ? path.dirname(jsonl) : path.join(home, 'sessions', '--C-dev-deepseek-harness--', sessionId);
  out.sessDir = sessDir;
  out.sessDirExists = fs.existsSync(sessDir);
  if (out.sessDirExists) {
    out.sessDirEntries = fs.readdirSync(sessDir);
    const jsonlPath = jsonl || path.join(sessDir, 'session.jsonl.zstd');
    out.jsonlPath = jsonlPath;
    out.jsonlExists = fs.existsSync(jsonlPath);
    if (out.jsonlExists) {
      const st = fs.statSync(jsonlPath);
      out.jsonlBytes = st.size;
      out.jsonlMtime = st.mtime.toISOString();
    }
  }

  // process tree for this daemon
  try {
    out.wmic = execSync(`wmic process where (ProcessId=${process.pid} or ProcessId=${process.ppid}) get ProcessId,ParentProcessId,Name,CommandLine /FORMAT:LIST`, { encoding: 'utf8', timeout: 8000 }).slice(0, 4000);
  } catch (e) {
    out.wmicError = String(e.stderr || e.message).slice(0, 500);
  }

  const ports = [3080, 3087, 3090, 4800, 4801, 3000, 4914];
  out.portTcp = await Promise.all(ports.map((p) => probePort(p)));

  out.http = {};
  for (const [name, url] of [
    ['gui3090', 'http://127.0.0.1:3090/'],
    ['gui3087', 'http://127.0.0.1:3087/'],
    ['gui3080', 'http://127.0.0.1:3080/'],
    ['acp4800', 'http://127.0.0.1:4800/'],
    ['acp4800health', 'http://127.0.0.1:4800/health'],
    ['acp4800ready', 'http://127.0.0.1:4800/ready'],
  ]) {
    out.http[name] = await get(url, name.includes('3080') ? 1500 : 2500);
  }

  // RPC on 3090 and 3087
  out.rpc = {};
  for (const port of [3090, 3087]) {
    out.rpc[port] = {};
    out.rpc[port].hostDescribe = await post(`http://127.0.0.1:${port}/api/host.describe`, {});
    out.rpc[port].sessionList = await post(`http://127.0.0.1:${port}/api/session.list`, {});
  }

  console.log(JSON.stringify(out, null, 2));
})().catch((e) => { console.error(e); process.exit(1); });
"}

