const { execSync, spawnSync } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');
const net = require('net');

function curl(url, extra = []) {
  const r = spawnSync('curl.exe', ['-sS', '-m', '3', '-D', '-', ...extra, url], { encoding: 'utf8', timeout: 8000, windowsHide: true });
  return { status: r.status, stdout: (r.stdout || '').slice(0, 2500), stderr: (r.stderr || '').slice(0, 400) };
}

function curlJson(url, payload) {
  const r = spawnSync('curl.exe', ['-sS', '-m', '4', '-H', 'content-type: application/json', '-d', JSON.stringify(payload), url], { encoding: 'utf8', timeout: 8000, windowsHide: true });
