function val(body) {
  return body && body.result && body.result.value;
}

const sessions3090 = val(inv.rpc3090sessions && inv.rpc3090sessions.body);
const sessions3087 = val(inv.rpc3087sessions && inv.rpc3087sessions.body);
const providers = val(inv.rpc3090llmProviders && inv.rpc3090llmProviders.body);
const models = val(inv.rpc3090llmModels && inv.rpc3090llmModels.body);

function slimSessions(v) {
  if (!v) return v;
  const arr = Array.isArray(v) ? v : (v.sessions || v.items || [v]);
  return arr.map(s => ({
    sessionId: s.sessionId || s.id,
    title: s.title,
    model: s.model,
    status: s.status,
    cwd: s.cwd,
    updatedAt: s.updatedAt || s.mtime,
    keys: Object.keys(s).slice(0, 20),
  }));
}

const out = {
  sessions3090: slimSessions(sessions3090),
  sessions3087: slimSessions(sessions3087),
  providers: Array.isArray(providers) ? providers.map(p => p.id || p.name || p) : providers,
  modelsHead: Array.isArray(models) ? models.slice(0, 15).map(m => m.id || m.name || m) : models,
};

// session.models with sessionId at body root
function rpcRoot(port, method, extra) {
  const payload = JSON.stringify({ method, sessionId: extra && extra.sessionId, ...extra });
  const r = spawnSync('curl.exe', ['-sS', '-m', '6', '-H', 'content-type: application/json', '-d', payload, 'http://127.0.0.1:' + port + '/api/' + method], { encoding: 'utf8', timeout: 10000, windowsHide: true });
  let parsed = r.stdout;
  try { parsed = JSON.parse(r.stdout); } catch {}
  return parsed;
}
const sessId = 'session-b883a0dd-7537-4905-b82a-0225b9a951ba';
out.models3090root = rpcRoot(3090, 'session.models', { sessionId: sessId });
out.models3087root = rpcRoot(3087, 'session.models', { sessionId: sessId });

// find writer.lock anywhere under .freddie/sessions
const sessRoot = path.join(os.homedir(), '.freddie', 'sessions');
out.sessionRoots = fs.existsSync(sessRoot) ? fs.readdirSync(sessRoot) : [];
function findLocks(dir, acc, depth) {
  if (depth > 4) return;
  let ents; try { ents = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
  for (const e of ents) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) findLocks(p, acc, depth+1);
    else if (e.name === 'writer.lock') acc.push({ p, content: fs.readFileSync(p, 'utf8').slice(0, 500) });
  }
}
out.locks = [];
if (fs.existsSync(sessRoot)) findLocks(sessRoot, out.locks, 0);

// decompress jsonl and count tool names
const jsonlPath = path.join(os.homedir(), '.freddie', 'sessions', '--C-dev-deepseek-harness--', sessId, 'session.jsonl.zstd');
out.jsonlPath = jsonlPath;
out.jsonlExists = fs.existsSync(jsonlPath);
if (out.jsonlExists) {
  // try zstd then gunzip
  let raw;
  const zstd = spawnSync('zstd.exe', ['-dc', jsonlPath], { encoding: 'buffer', timeout: 15000, windowsHide: true, maxBuffer: 50*1024*1024 });
  if (zstd.status === 0 && zstd.stdout && zstd.stdout.length) raw = zstd.stdout;
  else {
    try { raw = zlib.gunzipSync(fs.readFileSync(jsonlPath)); out.decomp = 'gzip'; }
    catch (e) {
      // try node zstd via exec of python?
      out.decompError = { zstdStatus: zstd.status, zstdErr: String(zstd.stderr||'').slice(0,200), gzip: String(e.message).slice(0,200) };
    }
  }
  if (raw) {
    const text = raw.toString('utf8');
    const lines = text.split(/\n/).filter(Boolean);
    out.eventCount = lines.length;
    const toolNames = {};
