      const t = ev.type || ev.event || ev.kind;
      const name = ev.name || (ev.payload && ev.payload.name) || (ev.tool && ev.tool.name) || (ev.data && ev.data.name);
      const blob = line;
      if (/mcp__gm__gm/.test(blob)) mcpGm++;
      if (/exec-spool[\\/]+in/.test(blob) && /pwsh/.test(blob)) pwshSpoolWrites++;
      if (name) {
        toolNames[name] = (toolNames[name] || 0) + 1;
        if (sampleTools.length < 30) sampleTools.push({ t, name, keys: Object.keys(ev).slice(0,12) });
      }
      if (name === 'pwsh') pwshCount++;
    }
    out.toolNames = toolNames;
    out.mcpGmMentions = mcpGm;
