const fs = require('fs');
const path = require('path');
const os = require('os');
const zlib = require('zlib');
const { spawnSync } = require('child_process');

const sessId = 'session-b883a0dd-7537-4905-b82a-0225b9a951ba';
const jsonlPath = path.join(os.homedir(), '.freddie', 'sessions', '--C-dev-deepseek-harness--', sessId, 'session.jsonl.zstd');
const buf = fs.readFileSync(jsonlPath);
const st = fs.statSync(jsonlPath);

// try decompress entire file with streaming zstd
let raw;
try {
  raw = zlib.zstdDecompressSync(buf, { maxOutputLength: 50 * 1024 * 1024 });
} catch (e) {
  raw = null;
  var err1 = String(e.message);
}

// if tiny, try concatenating frames
let frames = [];
if (!raw || raw.length < 1000) {
  // parse zstd skippable / frames
  let off = 0;
  const MAGIC = Buffer.from([0x28, 0xB5, 0x2F, 0xFD]);
  while (off + 4 <= buf.length) {
    const idx = buf.indexOf(MAGIC, off);
    if (idx < 0) break;
    frames.push(idx);
    off = idx + 4;
  }
}

const out = {
  jsonlBytes: st.size,
  syncLen: raw && raw.length,
  err1: typeof err1 !== 'undefined' ? err1 : null,
  frameOffsets: frames.slice(0, 20),
  frameCount: frames.length,
};

if (raw && raw.length > 0) {
  fs.writeFileSync('.gm/scratch/session-b883a0dd.jsonl', raw);
  out.preview = raw.toString('utf8').slice(0, 400);
}

// try decompress frame by frame
if (frames.length > 1) {
  const chunks = [];
  for (let i = 0; i < frames.length; i++) {
    const start = frames[i];
    const end = i + 1 < frames.length ? frames[i+1] : buf.length;
    try {
      const part = zlib.zstdDecompressSync(buf.subarray(start, end), { maxOutputLength: 20*1024*1024 });
      chunks.push(part);
    } catch (e) {
      chunks.push(Buffer.from('FRAME_ERR:' + e.message + '\n'));
    }
  }
  const all = Buffer.concat(chunks);
  fs.writeFileSync('.gm/scratch/session-b883a0dd.jsonl', all);
  out.concatLen = all.length;
  out.preview = all.toString('utf8').slice(0, 500);
}

// also inspect rpc-sessions rest: locks, models
const rs = JSON.parse(fs.readFileSync('.gm/scratch/rpc-sessions.json','utf8'));
out.locks = rs.locks;
out.models3090ok = !!(rs.models3090root && rs.models3090root.result);
out.models3090 = rs.models3090root && rs.models3090root.result;
out.models3087 = rs.models3087root && rs.models3087root.result;
out.providers = rs.providers;
out.sessionRoots = rs.sessionRoots;
out.decompMeta = { eventCount: rs.eventCount, mcpGmMentions: rs.mcpGmMentions, toolNames: rs.toolNames, decompError: rs.decompError };

fs.writeFileSync('.gm/scratch/jsonl-probe.json', JSON.stringify(out, null, 2));
process.stdout.write(JSON.stringify({
  jsonlBytes: out.jsonlBytes,
  syncLen: out.syncLen,
  concatLen: out.concatLen,
  frameCount: out.frameCount,
  preview: (out.preview||'').slice(0,200),
  locks: out.locks,
  sessionRoots: out.sessionRoots,
  models3090: out.models3090,
  providers: out.providers,
}));
"}

